document.addEventListener('DOMContentLoaded',function(){var tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));var tooltipList = tooltipTriggerList.map(function(tooltipTriggerEl){return new bootstrap.Tooltip(tooltipTriggerEl);});var popoverTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="popover"]'));var popoverList = popoverTriggerList.map(function(popoverTriggerEl){return new bootstrap.Popover(popoverTriggerEl);});document.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click',function(e){e.preventDefault();const target = document.querySelector(this.getAttribute('href'));if(target){target.scrollIntoView({behavior:'smooth',block:'start',});}});});const forms = document.querySelectorAll('.needs-validation');Array.prototype.slice.call(forms).forEach(function(form){form.addEventListener('submit',function(event){if(!form.checkValidity()){event.preventDefault();event.stopPropagation();}form.classList.add('was-validated');},false);});const alerts = document.querySelectorAll('.alert');alerts.forEach(function(alert){setTimeout(function(){const bsAlert = window.bootstrap && window.bootstrap.Alert ? new bootstrap.Alert(alert):null;if(bsAlert)bsAlert.close();},5000);});});window.APS ={showLoading:function(){const loader = document.createElement('div');loader.className = 'loading-spinner';loader.innerHTML = '<div class="spinner-border text-primary" role="status"><span class="visually-hidden">Loading...</span></div>';document.body.appendChild(loader);},hideLoading:function(){const loader = document.querySelector('.loading-spinner');if(loader){loader.remove();}},showNotification:function(message,type = 'info'){const notification = document.createElement('div');notification.className = `alert alert-${type}alert-dismissible fade show position-fixed top-0 end-0 m-3`;notification.style.zIndex = '9999';notification.innerHTML = ` ${message}<button type="button" class="btn-close" data-bs-dismiss="alert"></button> `;document.body.appendChild(notification);setTimeout(()=>{notification.remove();},5000);},formatCurrency:function(amount){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',}).format(amount);},debounce:function(func,wait){let timeout;return function executedFunction(...args){const later =()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout = setTimeout(later,wait);};},};